-- discrim-injure-raciste-voie-publique — Plusieurs passants ont entendu, aucun ne s'arrete
SELECT public.fn_cp_import_case('discrim-injure-raciste-voie-publique', '{"slug": "discrim-injure-raciste-voie-publique", "title": "Plusieurs passants ont entendu, aucun ne s''arrete", "theme_slug": "discriminations", "difficulty": "moyen", "is_free": false, "is_published": true, "status": "published", "year": 2026, "month": "Juillet", "total_points": 15, "estimated_minutes": 25, "situation_text": "Il est 16 heures. Dans une rue commercante animee, une femme vous signale avoir ete la cible d''une injure a caractere raciste de la part d''un homme qui s''est ensuite eloigne dans la foule. Plusieurs passants ont manifestement assiste a la scene, certains ralentissant le pas au moment des faits, mais aucun ne s''est arrete pour temoigner spontanement et la plupart poursuivent deja leur chemin. La victime, encore sous le choc, doute elle-meme d''etre prise au serieux, expliquant qu''on lui a deja dit par le passe qu''elle exagerait ce type de situation. L''auteur des faits n''est plus visible. Chaque minute qui passe reduit vos chances de recueillir des temoignages aupres des personnes presentes sur les lieux au moment des faits.", "questions": [{"position": 1, "max_points": 5, "label": "Comment agissez-vous dans l''immediat pour ne pas perdre les temoins presents au moment des faits ?", "hint": "Ces passants qui ont ralenti le pas se dispersent a chaque seconde qui passe.", "perfect": "Je releve les identites des temoins avant leur dispersion, cette action restant prioritaire compte tenu de la fugacite de leur presence sur ces lieux commercants. Je m''adresse directement aux personnes ayant visiblement ralenti le pas au moment des faits, sans attendre qu''elles se manifestent spontanement. Je recueille rapidement leurs coordonnees, meme sommaires, pour un contact ulterieur plus approfondi. Je reste attentive a ne pas negliger la victime pendant cette demarche, en la gardant informee de ce que j''entreprends.", "points": [{"position": 1, "label": "Relever les identites des temoins avant leur dispersion", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Poids fort du cas.", "groups": [{"position": 1, "keywords": ["temoins releves", "identites recueillies", "dispersion evitee"]}]}, {"position": 2, "label": "S''adresser directement aux passants ayant ralenti le pas", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Initiative active de recueil.", "groups": [{"position": 1, "keywords": ["passants sollicites", "initiative prise", "temoins approches"]}]}, {"position": 3, "label": "Recueillir rapidement des coordonnees meme sommaires", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Contact ulterieur possible.", "groups": [{"position": 1, "keywords": ["coordonnees recueillies", "contact possible", "recueil rapide"]}]}, {"position": 4, "label": "Garder la victime informee de cette demarche", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Victime non negligee pendant le recueil.", "groups": [{"position": 1, "keywords": ["victime informee", "attention maintenue", "demarche expliquee"]}]}]}, {"position": 2, "max_points": 5, "label": "Comment repondez-vous a cette victime qui doute elle-meme d''etre prise au serieux ?", "hint": "Un accueil passe defaillant a laisse une trace qu''il faut reconnaitre avant de pouvoir la depasser.", "perfect": "J''ecoute son recit avec une attention manifeste, sans laisser transparaitre le moindre doute sur la realite de ce qu''elle decrit. Je reconnais explicitement que cette injure constitue une infraction serieuse, sans attendre une confirmation par temoin pour valider la gravite de son ressenti. J''evoque, si cela est utile, les demarches concretes que je vais engager, pour qu''elle constate que sa parole entraine une action reelle. Je reste attentive au vecu qu''elle mentionne d''un accueil passe defaillant, sans le commenter mais en veillant a ne pas le reproduire.", "points": [{"position": 1, "label": "Ecouter son recit sans laisser transparaitre de doute", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Ecoute credible et attentive.", "groups": [{"position": 1, "keywords": ["ecoute attentive", "doute absent", "recit accueilli"]}]}, {"position": 2, "label": "Reconnaitre explicitement la gravite de cette injure", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Validation immediate de la gravite.", "groups": [{"position": 1, "keywords": ["gravite reconnue", "infraction nommee", "serieux affirme"]}]}, {"position": 3, "label": "Evoquer les demarches concretes engagees", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Action visible pour la victime.", "groups": [{"position": 1, "keywords": ["demarches evoquees", "action visible", "suite concrete"]}]}, {"position": 4, "label": "Ne pas reproduire l''accueil defaillant qu''elle a connu par le passe", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Vigilance sur l''accueil reserve.", "groups": [{"position": 1, "keywords": ["accueil ameliore", "vigilance appliquee", "confiance restauree"]}]}]}, {"position": 3, "max_points": 5, "label": "Comment formalisez-vous cette plainte pour qu''elle ait une chance reelle d''aboutir ?", "hint": "Sans description precise de l''auteur ni des temoins recueillis, ce dossier restera fragile.", "perfect": "Je recueille une description aussi precise que possible de l''auteur, meme si son visage n''est plus visible, tout element restant utile pour une identification ulterieure. Je retranscris fidelement les propos exacts tenus, sans les euphemiser ni les attenuer dans mon procès-verbal. Je joins a ce dossier les coordonnees des temoins recueillis, cette pièce restant determinante pour la suite de la procedure. J''informe la victime des suites possibles de cette plainte, sans lui promettre une issue que je ne peux garantir.", "points": [{"position": 1, "label": "Recueillir une description aussi precise que possible de l''auteur", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Identification facilitee.", "groups": [{"position": 1, "keywords": ["description recueillie", "auteur decrit", "identification facilitee"]}]}, {"position": 2, "label": "Retranscrire fidelement les propos exacts sans les attenuer", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Fidelite du proces-verbal.", "groups": [{"position": 1, "keywords": ["propos retranscrits", "attenuation evitee", "fidelite assuree"]}]}, {"position": 3, "label": "Joindre les coordonnees des temoins recueillis au dossier", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Dossier renforce par les temoignages.", "groups": [{"position": 1, "keywords": ["temoins joints", "dossier renforce", "coordonnees integrees"]}]}, {"position": 4, "label": "Informer des suites possibles sans promettre une issue certaine", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Realisme sur la procedure.", "groups": [{"position": 1, "keywords": ["suites expliquees", "promesse evitee", "realisme assure"]}]}]}]}'::jsonb);

-- discrim-refus-de-service-commerce — Le gerant invoque un service complet, la salle est a moitie vide
SELECT public.fn_cp_import_case('discrim-refus-de-service-commerce', '{"slug": "discrim-refus-de-service-commerce", "title": "Le gerant invoque un service complet, la salle est a moitie vide", "theme_slug": "discriminations", "difficulty": "difficile", "is_free": false, "is_published": true, "status": "published", "year": 2026, "month": "Juillet", "total_points": 15, "estimated_minutes": 30, "situation_text": "Il est 20 heures. Un couple vous signale s''etre vu refuser l''entree d''un restaurant, le gerant invoquant un service complet alors que la salle, visible depuis la vitrine, apparait a moitie vide. Le couple, d''origine etrangere, estime avoir ete refuse en raison de son apparence, precisant qu''un groupe de clients d''apparence differente est entre juste apres eux sans difficulte. Le gerant, interroge, maintient fermement son explication de service complet, evoquant des reservations non visibles depuis l''exterieur. Aucune preuve immediate ne permet de trancher entre ces deux versions, mais la disproportion entre la salle observee et le motif invoque interroge serieusement.", "questions": [{"position": 1, "max_points": 5, "label": "Comment evaluez-vous la plausibilite de ce motif de service complet ?", "hint": "Le prétexte commercial doit etre confronte a ce qui est objectivement observable.", "perfect": "Je constate objectivement les elements contredisant le pretexte, notamment le nombre de tables visiblement libres depuis la vitrine au moment des faits. Je demande au gerant des precisions concretes sur ces reservations invoquees, sans accepter cette explication sans verification. Je recueille le temoignage precis du couple sur la chronologie exacte des faits, y compris l''entree du groupe suivant. Je reste factuelle dans mes constatations, consignant ce que j''observe sans conclure prematurement sur l''intention du gerant.", "points": [{"position": 1, "label": "Constater objectivement les elements contredisant le pretexte", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Poids fort du cas.", "groups": [{"position": 1, "keywords": ["elements constates", "pretexte questionne", "contradiction objectivee"]}]}, {"position": 2, "label": "Demander des precisions concretes sur les reservations invoquees", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Verification active du motif.", "groups": [{"position": 1, "keywords": ["precisions demandees", "reservations verifiees", "motif questionne"]}]}, {"position": 3, "label": "Recueillir le temoignage precis du couple sur la chronologie", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Chronologie etablie.", "groups": [{"position": 1, "keywords": ["chronologie recueillie", "temoignage precise", "faits etablis"]}]}, {"position": 4, "label": "Rester factuelle sans conclure prematurement sur l''intention", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Prudence sur la qualification.", "groups": [{"position": 1, "keywords": ["conclusion differee", "prudence maintenue", "constat factuel"]}]}]}, {"position": 2, "max_points": 5, "label": "Comment gerez-vous cet echange avec le gerant qui maintient fermement sa version ?", "hint": "Le confronter frontalement sans elements suffisants pourrait fragiliser la suite de la procedure.", "perfect": "Je reste neutre et factuelle face a ce gerant, sans l''accuser directement de discrimination en l''absence de preuve formelle a ce stade. Je documente precisement sa version des faits, y compris les elements qu''il avance pour la justifier. Je l''informe des suites possibles de ce signalement, sans le menacer ni minimiser la gravite de l''accusation portee contre lui. Je recherche, si possible, des elements materiels verifiables comme un registre de reservations.", "points": [{"position": 1, "label": "Rester neutre et factuelle sans accuser directement", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Neutralite necessaire en l''absence de preuve formelle.", "groups": [{"position": 1, "keywords": ["neutralite maintenue", "accusation evitee", "posture factuelle"]}]}, {"position": 2, "label": "Documenter precisement sa version des faits", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Version du gerant consignee.", "groups": [{"position": 1, "keywords": ["version documentee", "explication consignee", "elements notes"]}]}, {"position": 3, "label": "Informer des suites possibles sans menacer ni minimiser", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Equilibre dans l''information donnee.", "groups": [{"position": 1, "keywords": ["suites expliquees", "menace evitee", "gravite reconnue"]}]}, {"position": 4, "label": "Rechercher des elements materiels verifiables comme un registre", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Verification objective recherchee.", "groups": [{"position": 1, "keywords": ["registre recherche", "elements verifiables", "preuve materielle"]}]}]}, {"position": 3, "max_points": 5, "label": "Comment orientez-vous cette affaire compte tenu de la difficulte a etablir une preuve formelle ?", "hint": "L''absence de preuve immediate ne signifie pas l''absence de toute suite possible.", "perfect": "Je recueille formellement la plainte de ce couple, cette formalisation restant necessaire meme si la preuve reste, a ce stade, difficile a etablir. Je consigne l''ensemble des elements objectifs disponibles, salle observee, chronologie, temoignage du groupe suivant si possible identifie. J''oriente ce couple vers les associations specialisees dans la lutte contre les discriminations, qui disposent parfois de moyens d''investigation complementaires. Je transmets ce dossier aux autorites competentes pour une appreciation approfondie que je ne peux mener seule sur place.", "points": [{"position": 1, "label": "Recueillir formellement la plainte malgre la difficulte probatoire", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Formalisation indispensable.", "groups": [{"position": 1, "keywords": ["plainte recueillie", "formalisation assuree", "difficulte reconnue"]}]}, {"position": 2, "label": "Consigner l''ensemble des elements objectifs disponibles", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Dossier complet constitue.", "groups": [{"position": 1, "keywords": ["elements consignes", "dossier complet", "objectivite assuree"]}]}, {"position": 3, "label": "Orienter vers les associations specialisees en discriminations", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Ressources complementaires proposees.", "groups": [{"position": 1, "keywords": ["association orientee", "specialisation proposee", "ressources indiquees"]}]}, {"position": 4, "label": "Transmettre ce dossier pour une appreciation approfondie", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Suite confiee aux autorites competentes.", "groups": [{"position": 1, "keywords": ["dossier transmis", "appreciation approfondie", "autorites saisies"]}]}]}]}'::jsonb);

-- discrim-agression-homophobe-sortie-bar — Ils etaient trois, la victime ne veut pas que ses parents l'apprennent
SELECT public.fn_cp_import_case('discrim-agression-homophobe-sortie-bar', '{"slug": "discrim-agression-homophobe-sortie-bar", "title": "Ils etaient trois, la victime ne veut pas que ses parents l''apprennent", "theme_slug": "discriminations", "difficulty": "difficile", "is_free": false, "is_published": true, "status": "published", "year": 2026, "month": "Juillet", "total_points": 15, "estimated_minutes": 30, "situation_text": "Il est 1 heure. A la sortie d''un bar, un jeune homme vous signale avoir ete agresse par trois individus qui l''ont insulte en raison de son orientation sexuelle avant de le frapper. Il presente des marques visibles au visage. Tres vite, il vous demande avec insistance que cette affaire ne remonte en aucun cas jusqu''a ses parents, expliquant ne pas leur avoir encore parle de son orientation et craignant que cette procedure ne les mette au courant malgre lui. Les trois agresseurs ont pris la fuite et ne sont plus visibles. Il insiste, entre inquietude pour cette confidentialite et besoin manifeste d''obtenir justice pour ce qu''il vient de subir.", "questions": [{"position": 1, "max_points": 5, "label": "Comment repondez-vous a sa demande de confidentialite tout en engageant les demarches necessaires ?", "hint": "Ces deux exigences, protection de sa vie privee et suite penale, ne sont pas contradictoires si elles sont bien expliquees.", "perfect": "Je garantis la confidentialite et caracterise le mobile, ces deux exigences pouvant etre tenues simultanement avec les precautions appropriees. Je lui explique precisement quelles informations seront necessairement consignees dans la procedure et lesquelles resteront a sa discretion, sans lui laisser de faux espoirs. Je le rassure sur le fait que la procedure penale ne suppose pas necessairement d''informer sa famille contre son gre. Je reste attentive a ne jamais prononcer devant des tiers des elements relatifs a son orientation sans son consentement explicite.", "points": [{"position": 1, "label": "Garantir la confidentialite et caracteriser le mobile", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Poids fort du cas.", "groups": [{"position": 1, "keywords": ["confidentialite garantie", "mobile caracterise", "double exigence tenue"]}]}, {"position": 2, "label": "Expliquer precisement ce qui sera consigne et ce qui reste discret", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Transparence sur le cadre procedural.", "groups": [{"position": 1, "keywords": ["cadre explique", "discretion precisee", "transparence assuree"]}]}, {"position": 3, "label": "Le rassurer sur l''absence d''information systematique de la famille", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Reassurance procedurale.", "groups": [{"position": 1, "keywords": ["famille non informee", "procedure clarifiee", "victime rassuree"]}]}, {"position": 4, "label": "Ne jamais evoquer son orientation devant des tiers sans son accord", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Vigilance continue sur la confidentialite.", "groups": [{"position": 1, "keywords": ["tiers proteges", "consentement respecte", "discretion maintenue"]}]}]}, {"position": 2, "max_points": 5, "label": "Comment caracterisez-vous le mobile de cette agression malgre la fuite des auteurs ?", "hint": "Sans les auteurs presents, seuls les propos rapportes et les circonstances permettent d''etablir ce mobile.", "perfect": "Je recueille precisement les propos exacts tenus par les agresseurs au moment des faits, ces mots restant determinants pour caracteriser ce mobile discriminatoire. Je consigne les circonstances completes de cette agression, y compris le lieu et le contexte de sortie de ce bar. Je constate et fais constater les blessures visibles, cette documentation medicale restant utile pour la suite de la procedure. Je recherche si d''eventuelles cameras de videoprotection du secteur ont pu capter la scene.", "points": [{"position": 1, "label": "Recueillir precisement les propos exacts tenus par les agresseurs", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Mobile caracterise par les propos.", "groups": [{"position": 1, "keywords": ["propos recueillis", "mobile etabli", "mots exacts consignes"]}]}, {"position": 2, "label": "Consigner les circonstances completes de l''agression", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Contexte etabli.", "groups": [{"position": 1, "keywords": ["circonstances consignees", "contexte etabli", "lieu precise"]}]}, {"position": 3, "label": "Constater et faire constater les blessures visibles", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Documentation medicale utile.", "groups": [{"position": 1, "keywords": ["blessures constatees", "documentation medicale", "constat effectue"]}]}, {"position": 4, "label": "Rechercher d''eventuelles cameras de videoprotection du secteur", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Preuve materielle complementaire.", "groups": [{"position": 1, "keywords": ["cameras recherchees", "videoprotection sollicitee", "preuve complementaire"]}]}]}, {"position": 3, "max_points": 5, "label": "Comment accompagnez-vous cette victime au-dela du strict recueil de cette plainte ?", "hint": "Cette agression, doublee de cette crainte de devoilement, laisse une victime particulierement fragilisee.", "perfect": "Je m''assure qu''il beneficie d''un examen medical adapte a ces blessures, cette demarche restant necessaire independamment de la suite penale. Je l''oriente vers des associations specialisees dans l''accompagnement des victimes de violences homophobes, disposant d''un savoir-faire particulier sur ces situations. Je reste attentive a ne pas le presser de questions supplementaires alors qu''il vient de vivre un choc double, l''agression et cette crainte de devoilement. Je lui indique comment il pourra suivre l''evolution de cette procedure sans crainte que sa famille en soit informee.", "points": [{"position": 1, "label": "S''assurer d''un examen medical adapte aux blessures", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Suivi medical necessaire.", "groups": [{"position": 1, "keywords": ["examen medical", "blessures suivies", "soins organises"]}]}, {"position": 2, "label": "Orienter vers des associations specialisees dans ces violences", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Accompagnement specialise propose.", "groups": [{"position": 1, "keywords": ["association orientee", "specialisation proposee", "accompagnement offert"]}]}, {"position": 3, "label": "Ne pas le presser de questions supplementaires face a ce double choc", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Menagement de la victime.", "groups": [{"position": 1, "keywords": ["questions menagees", "choc reconnu", "pression evitee"]}]}, {"position": 4, "label": "Indiquer comment suivre la procedure sans risque de devoilement", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Suivi discret propose.", "groups": [{"position": 1, "keywords": ["suivi discret", "procedure expliquee", "devoilement evite"]}]}]}]}'::jsonb);

-- discrim-harcelement-sexiste-transports — Il l'a suivie sur trois quais en commentant son physique
SELECT public.fn_cp_import_case('discrim-harcelement-sexiste-transports', '{"slug": "discrim-harcelement-sexiste-transports", "title": "Il l''a suivie sur trois quais en commentant son physique", "theme_slug": "discriminations", "difficulty": "moyen", "is_free": false, "is_published": true, "status": "published", "year": 2026, "month": "Juillet", "total_points": 15, "estimated_minutes": 25, "situation_text": "Il est 18 heures. Une jeune femme vous signale avoir ete suivie par un homme sur trois quais de RER successifs, celui-ci commentant de maniere insistante son physique et ses vetements sans jamais la toucher ni la menacer physiquement. Elle a change de quai a plusieurs reprises pour tenter de le semer, en vain, avant de finalement se diriger vers vous. Elle est visiblement pressee de reprendre son trajet et hesite a formaliser cette demarche, se demandant si l''absence de contact physique justifie vraiment de vous deranger pour cela. L''homme en question n''est plus visible sur le quai au moment ou elle vous parle.", "questions": [{"position": 1, "max_points": 5, "label": "Comment recevez-vous ce signalement alors qu''elle-meme doute de sa legitimite a se plaindre ?", "hint": "L''absence de contact physique n''enleve rien a la realite de ce qu''elle vient de vivre.", "perfect": "Je prends les faits au serieux malgre l''absence de contact, ce harcelement de rue constituant une infraction meme sans contact physique. Je lui explique clairement que sa demarche est parfaitement legitime, sans la laisser dans le doute sur ce point. J''ecoute son recit complet sans le minimiser, y compris le fait d''avoir change de quai a plusieurs reprises pour lui echapper. Je reste attentive a ne pas la presser malgre son envie de reprendre rapidement son trajet.", "points": [{"position": 1, "label": "Prendre les faits au serieux malgre l''absence de contact physique", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Poids fort du cas.", "groups": [{"position": 1, "keywords": ["faits pris au serieux", "absence de contact", "infraction reconnue"]}]}, {"position": 2, "label": "Expliquer clairement que sa demarche est legitime", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Legitimite affirmee explicitement.", "groups": [{"position": 1, "keywords": ["legitimite affirmee", "doute leve", "demarche validee"]}]}, {"position": 3, "label": "Ecouter son recit complet sans le minimiser", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Ecoute complete accordee.", "groups": [{"position": 1, "keywords": ["recit ecoute", "minimisation evitee", "attention accordee"]}]}, {"position": 4, "label": "Ne pas la presser malgre son envie de reprendre son trajet", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Respect de son besoin d''ecoute.", "groups": [{"position": 1, "keywords": ["patience accordee", "pression evitee", "ecoute respectee"]}]}]}, {"position": 2, "max_points": 5, "label": "Comment recueillez-vous des elements exploitables malgre la disparition de cet homme ?", "hint": "Un environnement de transports en commun offre souvent des ressources d''identification specifiques.", "perfect": "Je recueille une description precise de cet homme, y compris ses vetements et son itineraire sur ces trois quais successifs. Je sollicite les services de securite du reseau de transport pour verifier d''eventuelles cameras couvrant ces quais. J''interroge la victime sur d''eventuels autres voyageurs ayant pu remarquer ce comportement au fil de ces trois quais. Je consigne precisement l''horaire et le trajet exact pour faciliter cette recherche d''images.", "points": [{"position": 1, "label": "Recueillir une description precise incluant vetements et itineraire", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Elements d''identification recueillis.", "groups": [{"position": 1, "keywords": ["description precise", "itineraire etabli", "identification facilitee"]}]}, {"position": 2, "label": "Solliciter les services de securite du reseau pour les cameras", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Ressource specifique aux transports.", "groups": [{"position": 1, "keywords": ["securite sollicitee", "cameras verifiees", "reseau contacte"]}]}, {"position": 3, "label": "Interroger sur d''eventuels autres voyageurs temoins", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Temoins potentiels recherches.", "groups": [{"position": 1, "keywords": ["temoins recherches", "voyageurs interroges", "temoignages potentiels"]}]}, {"position": 4, "label": "Consigner precisement l''horaire et le trajet exact", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Precision utile pour la recherche d''images.", "groups": [{"position": 1, "keywords": ["horaire consigne", "trajet precise", "recherche facilitee"]}]}]}, {"position": 3, "max_points": 5, "label": "Comment cloturez-vous cette intervention en tenant compte de son besoin de reprendre son trajet ?", "hint": "Sa hate legitime de repartir ne doit pas se traduire par une prise en charge baclee.", "perfect": "Je formalise cette plainte de maniere complete malgre le temps limite dont elle dispose, sans sacrifier la qualite de ce recueil a la rapidite. Je lui remets les elements necessaires pour suivre cette procedure ou la completer ulterieurement si besoin. Je m''assure qu''elle puisse reprendre son trajet en toute securite, en verifiant que cet homme n''est plus dans les parages. Je reste disponible pour un complement d''information si elle se souvient d''autres details apres coup.", "points": [{"position": 1, "label": "Formaliser cette plainte de maniere complete malgre le temps limite", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Qualite du recueil preservee.", "groups": [{"position": 1, "keywords": ["plainte complete", "qualite preservee", "recueil soigne"]}]}, {"position": 2, "label": "Remettre les elements pour suivre ou completer la procedure", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Suivi facilite pour la victime.", "groups": [{"position": 1, "keywords": ["elements remis", "suivi facilite", "procedure accessible"]}]}, {"position": 3, "label": "S''assurer qu''elle puisse reprendre son trajet en securite", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Securite immediate verifiee.", "groups": [{"position": 1, "keywords": ["securite verifiee", "homme absent", "trajet securise"]}]}, {"position": 4, "label": "Rester disponible pour un complement d''information ulterieur", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Disponibilite future.", "groups": [{"position": 1, "keywords": ["disponibilite maintenue", "complement possible", "suivi propose"]}]}]}]}'::jsonb);

-- discrim-propos-discriminatoires-d-un-collegue-en-public — La remarque est faite devant la personne concernee
SELECT public.fn_cp_import_case('discrim-propos-discriminatoires-d-un-collegue-en-public', '{"slug": "discrim-propos-discriminatoires-d-un-collegue-en-public", "title": "La remarque est faite devant la personne concernee", "theme_slug": "discriminations", "difficulty": "expert", "is_free": false, "is_published": true, "status": "published", "year": 2026, "month": "Juillet", "total_points": 15, "estimated_minutes": 35, "situation_text": "Il est 15 heures. Lors d''une intervention conjointe, votre collegue tient une remarque a caractere discriminatoire visant directement l''usager que vous etes en train de controler, ce dernier l''entendant distinctement. L''usager se fige, visiblement blesse par ces propos, et vous regarde comme si vous alliez reagir. Votre collegue, lui, poursuit l''intervention comme si de rien n''etait, sans sembler mesurer la portee de ce qu''il vient de dire devant la personne concernee. Vous devez reagir immediatement, sur le terrain, sans pouvoir attendre un moment plus discret pour aborder cette faute avec votre collegue.", "questions": [{"position": 1, "max_points": 5, "label": "Comment reagissez-vous sur le moment, devant cet usager qui vient d''entendre cette remarque ?", "hint": "Ne rien dire reviendrait a cautionner ces propos aux yeux de la personne visee.", "perfect": "Je reprends l''echange et permets a la personne de faire valoir ses droits, cette reaction immediate restant indispensable devant l''usager lui-meme. Je marque clairement, meme brievement, ma desapprobation de ces propos, sans pour autant transformer cette intervention en conflit public avec mon collegue. Je m''adresse directement a l''usager pour reconnaitre que ces propos etaient inappropries, cette reconnaissance restant essentielle pour lui. Je poursuis l''intervention professionnelle en cours, sans la laisser totalement interrompue par cet incident.", "points": [{"position": 1, "label": "Reprendre l''echange et permettre a la personne de faire valoir ses droits", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Poids fort du cas.", "groups": [{"position": 1, "keywords": ["echange repris", "droits reconnus", "reaction immediate"]}]}, {"position": 2, "label": "Marquer clairement sa desapprobation sans transformer cela en conflit public", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Reaction mesuree mais nette.", "groups": [{"position": 1, "keywords": ["desapprobation marquee", "conflit evite", "reaction mesuree"]}]}, {"position": 3, "label": "S''adresser directement a l''usager pour reconnaitre l''inadaptation des propos", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Reconnaissance directe envers la victime.", "groups": [{"position": 1, "keywords": ["usager reconnu", "propos qualifies", "reconnaissance directe"]}]}, {"position": 4, "label": "Poursuivre l''intervention professionnelle en cours", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Continuite du service assuree.", "groups": [{"position": 1, "keywords": ["intervention poursuivie", "service assure", "continuite maintenue"]}]}]}, {"position": 2, "max_points": 5, "label": "Comment gerez-vous ensuite cette situation avec ce collegue, une fois cette intervention terminee ?", "hint": "Le moment public n''est pas celui du reglement de compte, mais le silence total ne peut pas non plus suivre.", "perfect": "Je m''entretiens avec ce collegue des la fin de cette intervention, sans laisser ce moment s''eloigner et perdre en clarte. Je lui explique factuellement en quoi ces propos etaient inacceptables, sans chercher a l''humilier pour autant dans cet echange. Je l''informe que je vais rendre compte de cet incident a ma hierarchie, sans le lui cacher ni le presenter comme une menace personnelle. Je reste attentive a l''evolution de son comportement lors des interventions suivantes que nous menerions ensemble.", "points": [{"position": 1, "label": "S''entretenir avec le collegue des la fin de l''intervention", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Reaction rapide et directe.", "groups": [{"position": 1, "keywords": ["entretien tenu", "collegue confronte", "reaction rapide"]}]}, {"position": 2, "label": "Expliquer factuellement en quoi ces propos etaient inacceptables", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Pedagogie sans humiliation.", "groups": [{"position": 1, "keywords": ["propos qualifies", "explication factuelle", "humiliation evitee"]}]}, {"position": 3, "label": "L''informer que cet incident sera rapporte a la hierarchie", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Transparence sur la suite donnee.", "groups": [{"position": 1, "keywords": ["hierarchie informee", "transparence assuree", "suite annoncee"]}]}, {"position": 4, "label": "Rester attentive a l''evolution de son comportement par la suite", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Vigilance continue.", "groups": [{"position": 1, "keywords": ["comportement surveille", "vigilance maintenue", "evolution suivie"]}]}]}, {"position": 3, "max_points": 5, "label": "Comment rendez-vous compte de cet incident a votre hierarchie ?", "hint": "Un compte rendu flou ou minimise n''aurait aucune utilite pour l''usager comme pour le service.", "perfect": "Je rends compte precisement des propos tenus par mon collegue, sans les euphemiser pour le proteger d''une consequence meritee. Je decris egalement ma propre reaction sur le terrain, cette transparence restant necessaire meme si elle expose ma propre gestion de la situation a l''appreciation de ma hierarchie. Je mentionne l''impact visible sur l''usager present, cet element restant central dans la gravite de cet incident. Je reste factuelle dans ce compte rendu, sans y ajouter d''appreciation personnelle sur la sanction qui devrait en decouler.", "points": [{"position": 1, "label": "Rendre compte precisement des propos tenus sans les euphemiser", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Fidelite du compte rendu.", "groups": [{"position": 1, "keywords": ["propos rapportes", "euphemisation evitee", "fidelite assuree"]}]}, {"position": 2, "label": "Decrire sa propre reaction sur le terrain avec transparence", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Transparence sur sa propre gestion.", "groups": [{"position": 1, "keywords": ["reaction decrite", "transparence assumee", "gestion exposee"]}]}, {"position": 3, "label": "Mentionner l''impact visible sur l''usager present", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Impact central de l''incident.", "groups": [{"position": 1, "keywords": ["impact mentionne", "usager considere", "gravite etablie"]}]}, {"position": 4, "label": "Rester factuelle sans appreciation personnelle sur la sanction", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Neutralite du compte rendu.", "groups": [{"position": 1, "keywords": ["compte rendu factuel", "sanction non commentee", "neutralite maintenue"]}]}]}]}'::jsonb);

-- discrim-victime-craint-de-ne-pas-etre-crue — On m'a deja dit que je devais avoir mal compris
SELECT public.fn_cp_import_case('discrim-victime-craint-de-ne-pas-etre-crue', '{"slug": "discrim-victime-craint-de-ne-pas-etre-crue", "title": "On m''a deja dit que je devais avoir mal compris", "theme_slug": "discriminations", "difficulty": "moyen", "is_free": false, "is_published": true, "status": "published", "year": 2026, "month": "Juillet", "total_points": 15, "estimated_minutes": 25, "situation_text": "Il est 14 heures. Au commissariat, un homme souhaite signaler des propos discriminatoires recus de facon repetee sur son lieu de travail. Des le debut de l''entretien, il precise qu''on lui a deja dit, lors d''une precedente demarche aupres d''un autre service, qu''il devait avoir mal compris ces propos, une reponse qui l''a durablement decourage d''entreprendre toute autre demarche. Il hesite visiblement a se livrer completement, guettant vos reactions au fil de son recit comme s''il s''attendait a rencontrer a nouveau ce scepticisme. Les faits qu''il decrit restent, pour l''instant, sans element materiel immediatement disponible pour les confirmer.", "questions": [{"position": 1, "max_points": 5, "label": "Comment menez-vous cet entretien pour restaurer une confiance deja entamee par une experience precedente ?", "hint": "Chaque hesitation qu''il manifeste renvoie probablement a ce scepticisme deja rencontre ailleurs.", "perfect": "Je restaure la confiance par une ecoute effective, cette exigence restant essentielle compte tenu de l''experience decourageante qu''il a deja vecue ailleurs. J''evite tout signe, meme involontaire, de doute ou d''impatience pendant son recit. Je le laisse s''exprimer a son rythme, sans le presser de conclure ou de synthetiser ce qu''il decrit. Je lui confirme explicitement que je prends sa demarche au serieux, cette reassurance restant utile compte tenu de son experience anterieure.", "points": [{"position": 1, "label": "Restaurer la confiance par une ecoute effective", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Poids fort du cas.", "groups": [{"position": 1, "keywords": ["confiance restauree", "ecoute effective", "attention manifestee"]}]}, {"position": 2, "label": "Eviter tout signe de doute ou d''impatience pendant le recit", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Attitude irreprochable pendant l''ecoute.", "groups": [{"position": 1, "keywords": ["doute absent", "impatience evitee", "attitude neutre"]}]}, {"position": 3, "label": "Le laisser s''exprimer a son rythme sans le presser", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Respect du rythme du recit.", "groups": [{"position": 1, "keywords": ["rythme respecte", "expression libre", "pression evitee"]}]}, {"position": 4, "label": "Confirmer explicitement que sa demarche est prise au serieux", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Reassurance explicite.", "groups": [{"position": 1, "keywords": ["serieux confirme", "demarche validee", "reassurance donnee"]}]}]}, {"position": 2, "max_points": 5, "label": "Comment recueillez-vous des elements exploitables malgre l''absence immediate de preuve materielle ?", "hint": "Le caractere repete de ces faits offre des pistes que des faits isoles n''offriraient pas.", "perfect": "Je recueille precisement la chronologie de ces propos repetes, dates approximatives, contextes, personnes eventuellement presentes lors de chaque episode. Je l''interroge sur d''eventuels collegues ayant pu assister a ces propos ou en avoir eu connaissance. Je verifie s''il dispose d''echanges ecrits, messages ou courriels, pouvant corroborer une partie de ces faits. Je consigne cette chronologie avec precision, meme en l''absence de preuve immediate, cette formalisation restant utile pour la suite.", "points": [{"position": 1, "label": "Recueillir precisement la chronologie de ces propos repetes", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Chronologie detaillee etablie.", "groups": [{"position": 1, "keywords": ["chronologie recueillie", "propos dates", "repetition documentee"]}]}, {"position": 2, "label": "Interroger sur d''eventuels collegues temoins", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Temoins potentiels recherches.", "groups": [{"position": 1, "keywords": ["collegues interroges", "temoins recherches", "presence verifiee"]}]}, {"position": 3, "label": "Verifier l''existence d''echanges ecrits pouvant corroborer les faits", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Preuve materielle recherchee.", "groups": [{"position": 1, "keywords": ["echanges verifies", "corroboration recherchee", "preuve materielle"]}]}, {"position": 4, "label": "Consigner cette chronologie avec precision malgre l''absence de preuve immediate", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Formalisation utile pour la suite.", "groups": [{"position": 1, "keywords": ["chronologie consignee", "formalisation assuree", "dossier prepare"]}]}]}, {"position": 3, "max_points": 5, "label": "Comment orientez-vous ce signalement pour eviter qu''il ne se decourage a nouveau ?", "hint": "Un dossier qui reste sans suite visible reproduirait exactement l''experience decevante qu''il a deja connue.", "perfect": "Je lui explique clairement les suites concretes de cette demarche, pour qu''il constate une difference tangible avec sa precedente experience decevante. Je l''oriente vers les dispositifs specialises en matiere de discrimination au travail, qui disposent de moyens d''investigation complementaires aux miens. Je lui indique comment il pourra suivre l''evolution de ce dossier, pour qu''il ne se retrouve pas a nouveau dans l''incertitude totale. Je reste factuelle sur les delais realistes de cette procedure, sans lui promettre une issue rapide que je ne peux garantir.", "points": [{"position": 1, "label": "Expliquer clairement les suites concretes de cette demarche", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Difference tangible avec l''experience anterieure.", "groups": [{"position": 1, "keywords": ["suites expliquees", "demarche concretisee", "difference constatee"]}]}, {"position": 2, "label": "Orienter vers les dispositifs specialises en discrimination au travail", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Ressources complementaires proposees.", "groups": [{"position": 1, "keywords": ["dispositif oriente", "specialisation proposee", "ressources indiquees"]}]}, {"position": 3, "label": "Indiquer comment suivre l''evolution de ce dossier", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Suivi transparent propose.", "groups": [{"position": 1, "keywords": ["suivi indique", "dossier accessible", "incertitude evitee"]}]}, {"position": 4, "label": "Rester factuelle sur les delais realistes sans promesse excessive", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Realisme sur la procedure.", "groups": [{"position": 1, "keywords": ["delais realistes", "promesse evitee", "honnetete assuree"]}]}]}]}'::jsonb);

